import { cache } from 'react'

export type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

export const getDashboardData = cache(async (): Promise<DashboardData> => {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
})

export function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p className="skeleton">$0</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p className="skeleton">0</p>
      </div>
    </div>
  )
}

export function RevenueChartSkeleton() {
  return (
    <div className="chart">
      <h2>Revenue</h2>
      <ul>
        {[...Array(6)].map((_, i) => (
          <li key={i} className="skeleton">
            Loading...
          </li>
        ))}
      </ul>
    </div>
  )
}

export function LatestInvoicesSkeleton() {
  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <ul>
        {[...Array(5)].map((_, i) => (
          <li key={i} className="skeleton">
            Loading invoice...
          </li>
        ))}
      </ul>
    </div>
  )
}

import { getDashboardData } from './lib/data'

export async function CardStats() {
  const { totalRevenue, totalInvoices } = await getDashboardData()

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{totalInvoices}</p>
      </div>
    </div>
  )
}

import { getDashboardData } from './lib/data'

export async function RevenueChart() {
  const { revenue } = await getDashboardData()

  return (
    <div className="chart">
      <h2>Revenue</h2>
      <ul>
        {revenue.map((item) => (
          <li key={item.month}>
            {item.month}: ${item.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

import { getDashboardData } from './lib/data'

export async function LatestInvoices() {
  const { invoices } = await getDashboardData()

  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <ul>
        {invoices.map((invoice) => (
          <li key={invoice.id}>
            {invoice.name} - ${invoice.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}
